nta.declaration:
// WashiBoot A/B boot policy, untimed finite-state model in UPPAAL.
// Sources: bootloader/include/boot/BootPolicy.hpp, bootloader/include/boot/BootMetadata.hpp,
// bootloader/src/main.cpp, core/src/main.cpp (application never confirms a boot).

const int MAX_UNCONFIRMED = 3;   // boot::MaxUnconfirmedBootAttempts
const int FALLBACK_RESETS = FALLBACK_RESETS_SELECT;   // 0 = shipped (F4 present), 1 = fixed: resetBootAttempts() on activation
const int APP_CONFIRMS = APP_CONFIRMS_SELECT;   // 0 = shipped application (never confirms), 1 = design intent

// FirmwareSlotState
const int EMPTY = 0; const int VALID = 1; const int PENDING = 2; const int CONFIRMED = 3; const int BAD = 4;
// BootSlot
const int SLOT_A = 0; const int SLOT_B = 1;

// Retained metadata (survives warm reset; scrubbed by cold start)
int[0,1] active = SLOT_A;
int[0,4] stateA = CONFIRMED;    // provisioned default: Slot A confirmed with baked CRC
int[0,4] stateB = EMPTY;
int[0,5] bootCount = 0;
bool confirmedFlag = false;     // BootMetadataConfirmed; the application never sets it
bool retainedCriticalFault = false;   // FaultLog holds TaskCheckinFailure/WatchdogTimeout
bool metadataCorrupt = false;

// Flash image validity, chosen by the environment (vector table + CRC together)
bool imageOkA = true;
bool imageOkB = false;

// Observables
int[0,1] launchedSlot = SLOT_A;
bool launchedInvalid = false;
bool safeLoop = false;
bool appRunning = false;   // Boot is in AppRunning (mirrors the location for use in guards)
int[0,5] pendingLaunches = 0;    // consecutive launches of a Pending slot (reset by a non-Pending launch, re-staging, or cold start)
bool launchedOverLimit = false;  // a Pending slot was launched although bootCount already exceeded MAX_UNCONFIRMED
bool fallbackLaunch = false;     // the most recent launch went through the fallback path
bool overLimitNonFallback = false;   // an over-limit Pending launch happened on the primary (non-fallback) path
bool lastLaunchOverLimit = false;    // the most recent launch was an over-limit Pending launch
int  safeReason = 0;   // Detail codes, abbreviated
const int R_FAULTLOG = 1; const int R_LOOP = 2; const int R_PRIOR = 3; const int R_NOSLOT = 6;

broadcast chan reset, coldStart;

bool bootable(int st) { return st == VALID || st == PENDING || st == CONFIRMED; }
int  stateOf(int slot) { return slot == SLOT_A ? stateA : stateB; }
bool imageOf(int slot) { return slot == SLOT_A ? imageOkA : imageOkB; }

template.declaration:
void normalizeConfirmed() {
    // BootMetadata.hpp:243-258
    if (confirmedFlag) {
        bootCount = 0; confirmedFlag = false;
        if (active == SLOT_A) stateA = CONFIRMED; else stateB = CONFIRMED;
    }
}
bool loopLimit() {
    // BootPolicy.hpp:126-131
    return stateOf(active) == PENDING && bootCount > MAX_UNCONFIRMED;
}
bool slotBootable(int slot) {
    // BootPolicy.hpp isSlotBootable: state, vector table, CRC (abstracted as imageOf)
    return bootable(stateOf(slot)) && imageOf(slot);
}
void launch(int slot, bool viaFallback) {
    // noteBootAttempt (BootMetadata.hpp:261-266) then jump
    lastLaunchOverLimit = false;
    if (stateOf(slot) == PENDING) {
        if (bootCount > MAX_UNCONFIRMED) {
            launchedOverLimit = true;
            lastLaunchOverLimit = true;
            if (!viaFallback) overLimitNonFallback = true;
        }
        if (pendingLaunches < 5) pendingLaunches++;
    } else {
        pendingLaunches = 0;
    }
    if (bootCount < 5) bootCount++;
    launchedSlot = slot;
    launchedInvalid = !imageOf(slot);
    fallbackLaunch = viaFallback;
    appRunning = true;
}
void activateFallback() {
    // BootPolicy.hpp:86-92. The fix inserts resetBootAttempts() before activateBootSlot(),
    // so the newly activated image starts its own attempt budget.
    active = 1 - active;
    if (FALLBACK_RESETS == 1) bootCount = 0;
}
void fail(int reason) { safeLoop = true; safeReason = reason; appRunning = false; }

// Environment may corrupt either image or stage a Pending image in Slot B
// before a reset. It never repairs an image silently (no in-field rewrite of
// Slot A/B is modelled; that mirrors docs/flight_provisioning.md).

nta.system:
B = Boot();
A = App();
F = Flash();
system B, A, F;
